/**
 * Before we start (punch list #382, PR 9): what the GC's page may show of a job, and what it may send back. The page
 * is off by default. It needs the job to share its stage dates, the job's own switch (*Show what we need before each
 * stage*), and then each bullet's eye. It shows the bullets on them alone: still needed on top, already settled
 * below, a bar for those bullets only, and after our Go with nothing open, the day the crew is confirmed for.
 *
 * It never shows a bullet of ours, what we saw beyond *we saw it on site*, a note, a name of ours, a trip, a cost, a
 * day they gave before, or the days they moved. Their press is a yes on their word, or with a photo a yes with
 * their photo. Nothing is ticked for them. Pure: `customer-portal` reads with it and `submit-portal-request` checks
 * an answer with it, from the edge's copy (`scripts/edge-kernels.mjs`).
 */
import { bulletIsYes, crewConfirmed, monthDay, readiness, settledWords, sharedBullets, waitsOnPhoto, weekDay, type GcPageSwitches } from './startChecks.ts'
import { stageFromRows, type StageLine, type StartCheckRows } from './startCheckRows.ts'

/** A bullet the page still needs: open, or a yes on their word that still waits on its photo. */
export type GcPageNeed = { id: string; words: string; wantsPhoto: boolean; waitsOnPhoto: boolean }
export type GcPageSettled = { id: string; words: string; how: string }
/** One stage on their page. `marks` is the bar, a box a shared bullet, the ones with a yes first. */
export type GcPageStage = { fixtureId: string; name: string; need: GcPageNeed[]; settled: GcPageSettled[]; marks: boolean[]; pct: number; crewConfirmedFor: string | null }

/** The stages of a job their page shows: unfinished, with a bullet the page may show. Empty with either switch off. */
export function gcPageStages(lines: readonly StageLine[], rows: StartCheckRows, switches: GcPageSwitches, dayOf: (iso: string) => string): GcPageStage[] {
  if (!switches.sharesStageDates || !switches.showsWhatWeNeed) return []
  const out: GcPageStage[] = []
  for (const line of [...lines].sort((a, b) => a.order - b.order)) {
    if (line.finished) continue
    const stage = stageFromRows(line, rows, { jobLabel: '', part: '', dayOf })
    const shown = sharedBullets(stage, switches)
    if (!shown.length) continue
    const ready = readiness(shown)
    out.push({
      fixtureId: line.fixtureId,
      name: line.name,
      need: shown.filter((b) => !bulletIsYes(b)).map((b) => ({ id: b.id, words: b.words, wantsPhoto: b.wantsPhoto, waitsOnPhoto: waitsOnPhoto(b) })),
      settled: shown.filter(bulletIsYes).map((b) => ({ id: b.id, words: b.words, how: settledWords(b) })),
      marks: [...Array<boolean>(ready.yes).fill(true), ...Array<boolean>(ready.total - ready.yes).fill(false)],
      pct: ready.pct,
      // The firm date is what they get for answering: our first day, once we said Go and nothing at all is open.
      crewConfirmedFor: crewConfirmed(stage) && stage.window ? stage.window[0] : null,
    })
  }
  return out
}

