// ---- what the page may send ------------------------------------------------------------------------

/** The most one answer may carry, and the most a job takes from its page in an hour. */
export const GC_PAGE_MAX_BULLETS = 40
export const GC_PAGE_MAX_ANSWERS_PER_HOUR = 120
export const GC_PAGE_MAX_DAYS_PER_HOUR = 10
export const GC_PAGE_MAX_PHOTO_SIGNS_PER_HOUR = 40
/** The bucket's own cap, said here so the page shrinks a photo to fit before it asks. */
export const GC_PAGE_PHOTO_MAX_BYTES = 2 * 1024 * 1024
export const GC_PAGE_PHOTO_TYPES: readonly string[] = ['image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif']
/** How a yes from their page is kept: who, in the customer's name, and how it reached us. */
export const GC_PAGE_HOW = 'on their page'

export type GcPagePhoto = { bulletId: string; path: string; fileName: string; bytes: number }
/** One send from their page: the bullets they say are ready, a photo for any of them, and a day it will be ready. */
export type GcPageAnswer = { fixtureId: string; ready: string[]; photos: GcPagePhoto[]; readyDay: string | null }

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
const YMD = /^\d{4}-\d{2}-\d{2}$/
const str = (v: unknown): string => (typeof v === 'string' ? v.trim() : '')

/** A body read into an answer, or the reason it is refused. It trusts nothing: every id is checked against the stage after. */
export function parseGcPageAnswer(body: Record<string, unknown>): { ok: true; answer: GcPageAnswer } | { ok: false; why: string } {
  const fixtureId = str(body.fixtureId)
  if (!UUID.test(fixtureId)) return { ok: false, why: 'That stage could not be found.' }
  const ready = Array.isArray(body.ready) ? [...new Set(body.ready.map(str))] : []
  if (ready.some((id) => !UUID.test(id)) || ready.length > GC_PAGE_MAX_BULLETS) return { ok: false, why: 'That list could not be read.' }
  const photos: GcPagePhoto[] = []
  for (const p of Array.isArray(body.photos) ? body.photos : []) {
    const o = (p ?? {}) as Record<string, unknown>
    const photo = { bulletId: str(o.bulletId), path: str(o.path), fileName: str(o.fileName).slice(0, 200) || 'photo.jpg', bytes: Number(o.bytes) || 0 }
    if (!UUID.test(photo.bulletId) || !photo.path || photo.path.length > 300 || photo.bytes < 0 || photo.bytes > GC_PAGE_PHOTO_MAX_BYTES) return { ok: false, why: 'That photo could not be read.' }
    photos.push(photo)
  }
  if (photos.length > GC_PAGE_MAX_BULLETS) return { ok: false, why: 'That list could not be read.' }
  const readyDay = str(body.readyDay) || null
  if (readyDay && !YMD.test(readyDay)) return { ok: false, why: 'That day could not be read.' }
  if (!ready.length && !photos.length && !readyDay) return { ok: false, why: 'Tick what is ready, or give a day.' }
  return { ok: true, answer: { fixtureId, ready, photos, readyDay } }
}

/**
 * An answer held against what their page shows of the stage right now. A bullet that is not on the page (hidden, of
 * ours, taken off, already settled) is refused, so a stale page cannot tick what it no longer shows. A day must be
 * today or after, and within two years.
 */
export function gcPageAnswerProblem(answer: GcPageAnswer, stage: GcPageStage | undefined, todayYmd: string): string | null {
  if (!stage) return 'That stage is not on your page any more. Please open the page again.'
  const needed = new Set(stage.need.map((b) => b.id))
  const asked = [...answer.ready, ...answer.photos.map((p) => p.bulletId)]
  if (asked.some((id) => !needed.has(id))) return 'Your page has changed. Please open it again.'
  if (answer.readyDay) {
    if (answer.readyDay < todayYmd) return 'Please pick today or a day after it.'
    if (Number(answer.readyDay.slice(0, 4)) > Number(todayYmd.slice(0, 4)) + 2) return 'Please pick a day within two years.'
  }
  return null
}

/** The path a photo from their page is kept at: the job's folder, as the bucket's own rule reads it. */
export const gcPagePhotoPath = (jobId: string, bulletId: string, ms: number): string => `${jobId}/page-${bulletId}-${ms}.jpg`
/** A path their page hands back is one this job's page was given for this bullet. */
export const gcPagePhotoPathOk = (path: string, jobId: string, bulletId: string): boolean => new RegExp(`^${jobId}/page-${bulletId}-\\d{10,16}\\.jpg$`).test(path)

/** *Nov 25*, for a line that names a day in passing. */
export const gcPageDay = monthDay
